/// Split CSV text into records, each a vector of field strings, or return
/// None if the text is malformed.
/// - Records are separated by a newline "\n", or by "\r\n" (the "\r" is
///   dropped). A "\r" that is not directly followed by "\n" is an ordinary
///   character. One record separator at the very end of the text does not start
///   another record. The empty text has no records: vec![].
/// - Fields are separated by ",". A record with k commas has k + 1 fields, so an
///   empty line is the record vec![""].
/// - A field whose first character is '"' is quoted: it runs to the next '"'
///   that is not part of a doubled '""'. Inside it, '""' stands for one '"',
///   and ",", "\r" and "\n" are ordinary characters. The closing quote must be
///   followed by ",", a record separator, or the end of the text; anything else
///   is malformed. A quoted field with no closing quote is malformed.
/// - Any other field is unquoted and runs to the next "," or record separator.
///   An unquoted field that contains '"' is malformed.
/// - Spaces are kept as they are: ' a ' is the field " a ", and ' "a"' is an
///   unquoted field containing '"', hence malformed.
/// >>> parse_csv(String::from("name,note\n\"Smith, J\",\"say \"\"hi\"\" now\"\n"))
/// Some(vec![vec![String::from("name"), String::from("note")], vec![String::from("Smith, J"), String::from("say \"hi\" now")]])
/// >>> parse_csv(String::from("a,b\"c"))
/// None
fn parse_csv(text: String) -> Option<Vec<Vec<String>>> {
    let cs: Vec<char> = text.chars().collect();
    let n = cs.len();
    let at_separator = |j: usize| j < n && (cs[j] == '\n' || (cs[j] == '\r' && j + 1 < n && cs[j + 1] == '\n'));
    let mut records: Vec<Vec<String>> = Vec::new();
    let mut record: Vec<String> = Vec::new();
    let mut i = 0;
    if n == 0 {
        return Some(records);
    }
    loop {
        let mut field = String::new();
        if cs[i..].first() == Some(&'"') {
            i += 1;
            loop {
                if i >= n {
                    return None;
                }
                if cs[i] == '"' {
                    if i + 1 < n && cs[i + 1] == '"' {
                        field.push('"');
                        i += 2;
                        continue;
                    }
                    i += 1;
                    break;
                }
                field.push(cs[i]);
                i += 1;
            }
        } else {
            while i < n && cs[i] != ',' && !at_separator(i) {
                if cs[i] == '"' {
                    return None;
                }
                field.push(cs[i]);
                i += 1;
            }
        }
        record.push(field);
        if i >= n {
            records.push(record);
            return Some(records);
        }
        if cs[i] == ',' {
            i += 1;
            continue;
        }
        if !at_separator(i) {
            return None;
        }
        i += if cs[i] == '\r' { 2 } else { 1 };
        records.push(std::mem::take(&mut record));
        if i >= n {
            return Some(records);
        }
    }
}
